import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac
import time
import base64

app = Flask(__name__)
DATABASE = '/var/data/app.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT, email TEXT, role TEXT)')
    db.execute('CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY, action TEXT, timestamp REAL)')
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role) VALUES (1, 'admin', 'admin@corp.internal', 'admin')")
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role) VALUES (2, 'jsmith', 'jsmith@corp.internal', 'user')")
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role) VALUES (3, 'analyst', 'analyst@corp.internal', 'readonly')")
    db.commit()
    db.close()

def verify_token(token):
    """Verify HMAC-based session token. Returns username or None."""
    try:
        parts = base64.b64decode(token).decode().split(':')
        if len(parts) != 3:
            return None
        username, timestamp, signature = parts
        expected = hmac.new(SECRET_KEY.encode(), f"{username}:{timestamp}".encode(), hashlib.sha256).hexdigest()[:16]
        if hmac.compare_digest(signature, expected):
            if time.time() - float(timestamp) < 86400:
                return username
    except Exception:
        pass
    return None

@app.route('/api/users/search')
def search_users():
    """Search users by name or email. Supports partial matching."""
    auth = request.headers.get('X-Auth-Token')
    if not auth or not verify_token(auth):
        return jsonify({'error': 'unauthorized'}), 401

    query = request.args.get('q', '')
    field = request.args.get('field', 'username')

    # Validate field to prevent injection in column name
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'invalid field'}), 400

    # Build search query - field is validated above but query value is user-controlled
    sql = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{query}%'"

    db = get_db()
    try:
        results = db.execute(sql).fetchall()
        return jsonify([dict(r) for r in results])
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>')
def get_user(user_id):
    """Get user details by ID."""
    auth = request.headers.get('X-Auth-Token')
    if not auth or not verify_token(auth):
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    user = db.execute('SELECT id, username, email, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'not found'}), 404

@app.route('/api/audit', methods=['POST'])
def log_audit():
    """Log an audit event."""
    auth = request.headers.get('X-Auth-Token')
    if not auth or not verify_token(auth):
        return jsonify({'error': 'unauthorized'}), 401

    data = request.get_json()
    action = data.get('action', 'unknown')
    db = get_db()
    db.execute('INSERT INTO audit_log (action, timestamp) VALUES (?, ?)', (action, time.time()))
    db.commit()
    return jsonify({'status': 'logged'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
